import { mkdirSync } from "node:fs";
import { dirname } from "node:path";
import { drizzle } from "drizzle-orm/node-sqlite";
import * as schema from "./schema.js";
export { schema };

/** SQLite file path from the project root, read from `DATABASE_URL` with the same fallback as `config.ts` */
export const DB_FILE = process.env.DATABASE_URL ?? "db/db.sqlite";

// Create the database folder first, since SQLite only creates the file.
mkdirSync(dirname(DB_FILE), { recursive: true });

/** Drizzle client on Node's built-in `node:sqlite`, with `db.query` typed from the schema relations */
export const db = drizzle({ connection: DB_FILE, relations: schema.relations });

// Let reads run while a write is in progress, and enforce foreign keys such as sessions → users.
db.$client.exec("PRAGMA journal_mode = WAL; PRAGMA foreign_keys = ON;");

import { defineRelations } from "drizzle-orm";
import { integer, sqliteTable, text } from "drizzle-orm/sqlite-core";

/** Users who signed in with an OAuth provider */
export const users = sqliteTable("users", {
	/** User id */
	id: text().primaryKey(),
	/** Verified email, used to match returning users */
	email: text().notNull().unique(),
	/** Avatar URL from the provider */
	image: text().notNull(),
	/** When the user first signed in */
	createdAt: integer({ mode: "timestamp_ms" }).notNull(),
	/** When the user last signed in */
	updatedAt: integer({ mode: "timestamp_ms" }).notNull(),
});

/** Login sessions; deleting a user deletes their sessions */
export const sessions = sqliteTable("sessions", {
	/** SHA-256 hash of the session cookie token */
	id: text().primaryKey(),
	/** Id of the user who owns the session */
	userId: text()
		.notNull()
		.references(() => users.id, { onDelete: "cascade" }),
	/** When the session stops being valid */
	expiresAt: integer({ mode: "timestamp_ms" }).notNull(),
});

/** Links between tables, used by `db.query` to load related rows */
export const relations = defineRelations({ users, sessions }, (r) => ({
	users: {
		/** Sessions the user owns */
		sessions: r.many.sessions(),
	},
	sessions: {
		/** User who owns the session */
		user: r.one.users({ from: r.sessions.userId, to: r.users.id }),
	},
}));

import { mkdirSync } from "node:fs";
import { dirname } from "node:path";
import { defineConfig } from "drizzle-kit";

// Read the path from `DATABASE_URL`, and keep the fallback in sync with `DB_FILE` in `src/lib/server/drizzle/index.ts`.
const DB_FILE = process.env.DATABASE_URL ?? "db/db.sqlite";

// Create the database folder first, since SQLite only creates the file.
mkdirSync(dirname(DB_FILE), { recursive: true });

/** drizzle-kit settings; run it with `--config=src/lib/server/drizzle/config.ts`, and paths resolve from the project root */
export default defineConfig({
	dialect: "sqlite",
	schema: "./src/lib/server/drizzle/schema.ts",
	out: "./src/lib/server/drizzle/migrations",
	dbCredentials: { url: DB_FILE },
});
